$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$component = Decode ""

$pagePath = Join-Path $root "app\provider\payments\page.tsx"
$componentPath = Join-Path $root "app\provider\payments\FinanceReconciliationStatus.tsx"
$financePath = Join-Path $root "app\api\provider\finance\route.ts"
$auditPath = Join-Path $root "app\api\provider\finance-audit\route.ts"

foreach ($path in @($pagePath, $financePath, $auditPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "13.13 : fichier requis introuvable : $path"
    }
}

$page = [System.IO.File]::ReadAllText($pagePath)
$finance = [System.IO.File]::ReadAllText($financePath)
$audit = [System.IO.File]::ReadAllText($auditPath)

if (-not $finance.Contains("KLYX_CANONICAL_FINANCE_RECONCILIATION_13_12")) {
    throw "13.13 : KLYX 13.12 introuvable."
}

if (-not $page.Contains("KLYX_GROUP_FINANCE_AUDIT_PAGE_13_03")) {
    throw "13.13 : page finance 13.03 introuvable."
}

if (-not $audit.Contains("KLYX_GROUP_FINANCE_AUDIT_API_13_03")) {
    throw "13.13 : API audit 13.03 introuvable."
}

if ($page.Contains("KLYX_FINANCE_RECONCILIATION_PAGE_13_13")) {
    Write-Host "KLYX 13.13 deja applique."
    exit 0
}

$auditRender = [regex]::Match($page, '(?m)^(\s*)<ProviderFinanceAudit\b')

if (-not $auditRender.Success) {
    throw "13.13 : rendu ProviderFinanceAudit introuvable. Aucun fichier modifie."
}

$firstImportIndex = $page.IndexOf("import ")

if ($firstImportIndex -lt 0) {
    throw "13.13 : imports page.tsx introuvables. Aucun fichier modifie."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

Copy-Item -LiteralPath $pagePath -Destination ($pagePath + ".bak-13-13-" + $timestamp) -Force

if (Test-Path -LiteralPath $componentPath) {
    Copy-Item -LiteralPath $componentPath -Destination ($componentPath + ".bak-13-13-" + $timestamp) -Force
}

$importLine = 'import FinanceReconciliationStatus from "./FinanceReconciliationStatus";' + "`r`n"

$page = $page.Insert($firstImportIndex, $importLine)

# Le premier insert decale l index du rendu audit.
$auditRender = [regex]::Match($page, '(?m)^(\s*)<ProviderFinanceAudit\b')

if (-not $auditRender.Success) {
    throw "13.13 : rendu audit perdu apres import."
}

$indent = $auditRender.Groups[1].Value

$ui =
    $indent + "{/* KLYX_FINANCE_RECONCILIATION_PAGE_13_13 */}" + "`r`n" +
    $indent + "<FinanceReconciliationStatus />" + "`r`n`r`n"

$page = $page.Insert($auditRender.Index, $ui)

[System.IO.File]::WriteAllText($componentPath, $component, $utf8)
[System.IO.File]::WriteAllText($pagePath, $page, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 13.13 APPLIQUE"
Write-Host "======================================"
Write-Host "Finances coherentes : VERT"
Write-Host "Difference detectee : ALERTE"
Write-Host "Differences : DETAILLEES"
Write-Host "Reverification : MANUELLE"
Write-Host "Audit 13.03 : CONSERVE"
Write-Host "Correction automatique : NON"
Write-Host "Ledger : INCHANGE"
Write-Host "Stripe : INCHANGE"
Write-Host "Migration : AUCUNE"
Write-Host "======================================"
